"""Build the standalone motion edition. Requires: python -m pip install markdown."""
from pathlib import Path
import re, html, base64
import markdown
from markdown.extensions.toc import slugify_unicode
root=Path(__file__).resolve().parent
source=(root/'OOP_CPP20_Полная_подготовка_к_контрольной.md').read_text()
base=(root/'OOP_CPP20_Тренажёр.html').read_text()
rendered=markdown.markdown(source,extensions=['fenced_code','tables','toc','sane_lists'],extension_configs={'toc':{'slugify':slugify_unicode}})
rendered=re.sub(r'src="(assets/[^\"]+\.svg)"',lambda m:'src="data:image/svg+xml;base64,'+base64.b64encode((root/m[1]).read_bytes()).decode()+'"',rendered)
sections=[]
for index,ch in enumerate(re.split(r'(?=<h1\b)',rendered)):
 heading=re.search(r'<h1[^>]*>(.*?)</h1>',ch,re.S)
 if not heading:continue
 title=re.sub('<[^>]+>','',heading[1]); lm=re.search(r'Лекция (\d)',title)
 if index<=1 and not lm:continue
 lecture=int(lm[1]) if lm else 0; ident='lecture-'+str(lecture) if lecture else 'extra-'+str(index)
 parts=re.split(r'(?=<h2\b)',ch); out=parts[0]
 for part in parts[1:]:
  m=re.match(r'<h2([^>]*)>(.*?)</h2>(.*)',part,re.S)
  if m:
   attrs,head,body=m.groups()
   out+=f'<details class="topic" {attrs}><summary><span>{head}</span><b aria-hidden="true">+</b></summary><div class="topic-body">{body}</div></details>'
  else:out+=part
 sections.append(f'<section class="lesson" id="{ident}" data-lecture="{lecture}">{out}</section>')
base=re.sub(r'(<div id="reading">).*?(</div><p class="empty" id="no-results")',lambda m:m[1]+''.join(sections)+m[2],base,flags=re.S)
