base=re.sub(r'<style>.*?</style>',lambda m:'<style>'+css+'</style>',base,flags=re.S)
base=base.replace('<body id="top">','<body id="top"><a class="skip-link" href="#workspace">Перейти к обучению</a>')
header='''<header><div class="bar"><a class="logo" href="#top">OBJECT<em>++</em></a><span class="small">C++20 / THE LEARNING EXPERIENCE</span><nav class="topnav" aria-label="Режим обучения"><button data-mode="read" class="active" aria-pressed="true">Конспект</button><button data-mode="cards" aria-pressed="false">Карточки</button><button data-mode="quiz" aria-pressed="false">Проверка</button></nav><button class="motion-switch" id="motion-toggle" aria-pressed="true">MOTION ON</button></div><div class="scroll-track" aria-hidden="true"></div></header>'''
base=re.sub(r'<header>.*?</header>',lambda m:header,base,count=1,flags=re.S)
hero='''<section class="hero"><div class="hero-copy"><div class="eyebrow">ООП / C++20 / ВОСЕМЬ ЛЕКЦИЙ</div><h1><span>СНАЧАЛА</span><span class="outline">ПОНЯТЬ.</span><span>ПОТОМ</span><span class="lime">НАПИСАТЬ.</span></h1><p>Не заучивай синтаксис. Разберись, как живёт объект. От первой переменной до класса, который управляет своим ресурсом.</p><div class="hero-actions"><button class="primary" id="start-init">Начать с инициализации</button><button class="secondary" data-mode="quiz">Проверить себя</button></div></div><div class="scene" aria-label="Три составляющие объекта: состояние, поведение и время жизни"><div class="scene-grid" aria-hidden="true"></div><div class="orbit" aria-hidden="true"></div><div class="object-rig"><div class="slab back"><small>03 / LIFETIME</small><strong>Время жизни.</strong><code>~Object();</code></div><div class="slab mid"><small>02 / BEHAVIOR</small><strong>Поведение.</strong><code>void transform();</code></div><div class="slab front"><small>01 / STATE</small><strong>Состояние.</strong><div class="slab-foot"><code>class Object { ... };</code><b>{ }</b></div></div></div><div class="scene-note top">OBJECT MODEL<b>ТРИ СТОРОНЫ ОДНОГО ОБЪЕКТА</b></div><div class="scene-label">OWN THE RESOURCE.<br>UNDERSTAND THE LIFETIME.</div><div class="scene-note bottom">ИНКАПСУЛЯЦИЯ · RAII · ПОЛИМОРФИЗМ</div></div><div class="hero-scroll">SCROLL TO UNDERSTAND <i aria-hidden="true"></i></div></section>'''
base=re.sub(r'<section class="hero">.*?</section>',lambda m:hero,base,count=1,flags=re.S)
words='C++20 <i>✳</i> ОБЪЕКТЫ <i>✳</i> ВРЕМЯ ЖИЗНИ <i>✳</i> КЛАССЫ <i>✳</i> ВЛАДЕНИЕ <i>✳</i> '
ticker='<div class="ticker" aria-hidden="true"><div class="ticker-track"><span>'+words+'</span><span>'+words+'</span></div></div>'
intro='''<section class="intro reveal"><h2>Восемь лекций.<br>Одна <em>связная<br>картина.</em></h2><div><p>Сначала — фундамент языка. Затем — классы, ресурсы и отношения между объектами. Каждая новая тема опирается на предыдущую.</p><p>Открой раздел. Разбери пример. Закрой ответ и объясни правило своими словами. Если не получилось — вернись к нему в карточках.</p><span class="micro">01—04 ОСНОВЫ / 05—08 ОБЪЕКТНАЯ МОДЕЛЬ</span></div></section>'''
titles=['Язык и типы','Операторы','Память и ссылки','Функции','Классы','Ресурсы и RAII','Перегрузка','Наследование']
route='<nav class="route reveal" aria-label="Быстрый переход по курсу">'+''.join(f'<a href="#lecture-{i}" data-route="{i}"><small>CHAPTER / 0{i}</small><strong>{t}</strong><b aria-hidden="true">↗</b></a>' for i,t in enumerate(titles,1))+'</nav>'
base=base.replace('<div class="stats">',ticker+intro+route+'<div class="stats reveal">',1)
base=base.replace('<div class="layout">','<div class="section-caption"><span>THE STUDY ROOM / УЧЕБНОЕ ПРОСТРАНСТВО</span><span>ЧИТАЙ. ПРОВЕРЯЙ. ПОВТОРЯЙ.</span></div><div class="layout" id="study-room">',1)
base=base.replace('Интерфейс вдохновлён','Учебная механика вдохновлена')
base=base.replace('</footer></div>','</footer><div class="foot-brand" aria-hidden="true">OBJECT++</div></div>',1)
base=base.replace("const KEY='oop-study-v1'", "const KEY='oop-study-v1'")
# Обновляем символы и статистику без зависимости от старой версии конспекта.
base=base.replace('href="#extra-10" id="summary-link"','href="#extra-10" id="summary-link"')
# Управление анимацией и декоративные эффекты не вмешиваются в учебную логику.
motion=r'''
<script>
(()=>{
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
 const toggle=document.getElementById('motion-toggle');
 let explicit=null;try{const stored=localStorage.getItem('oop-motion');if(stored==='on'||stored==='off')explicit=stored}catch(e){}
 let enabled=explicit?explicit==='on':!reduced.matches;
 const motionAllowed=()=>enabled&&!reduced.matches;
 function updateMotion(){const on=motionAllowed();document.body.classList.toggle('motion-off',!on);toggle.textContent=on?'MOTION ON':'MOTION OFF';toggle.setAttribute('aria-pressed',String(on));toggle.title=reduced.matches?'Анимация отключена настройкой системы':'Включить или отключить анимацию';}
 toggle.addEventListener('click',()=>{enabled=!enabled;try{localStorage.setItem('oop-motion',enabled?'on':'off')}catch(e){}updateMotion()});
 reduced.addEventListener('change',updateMotion);updateMotion();
 const hero=document.querySelector('.hero'),scene=document.querySelector('.scene');
 hero.dataset.entered='';
 if('IntersectionObserver' in window){
  const ambient=new IntersectionObserver(entries=>entries.forEach(entry=>{document.body.classList.toggle(entry.target===hero?'ambient-running':'ticker-running',entry.isIntersecting)}));ambient.observe(hero);ambient.observe(document.querySelector('.ticker'));
  const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');reveal.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('ready');reveal.observe(el)});
 }
 scene.addEventListener('pointermove',e=>{if(!motionAllowed()||e.pointerType==='touch')return;const r=scene.getBoundingClientRect();scene.style.setProperty('--rx',((.5-(e.clientY-r.top)/r.height)*10)+'deg');scene.style.setProperty('--ry',(((e.clientX-r.left)/r.width-.5)*16)+'deg')});
 scene.addEventListener('pointerleave',()=>{scene.style.setProperty('--rx','0deg');scene.style.setProperty('--ry','0deg')});
 document.addEventListener('visibilitychange',()=>{document.body.style.setProperty('--tab-visible',document.hidden?'0':'1');if(document.hidden){document.body.classList.remove('ambient-running','ticker-running')}else{const r=hero.getBoundingClientRect();document.body.classList.toggle('ambient-running',r.bottom>0&&r.top<innerHeight);const t=document.querySelector('.ticker').getBoundingClientRect();document.body.classList.toggle('ticker-running',t.bottom>0&&t.top<innerHeight)}});
 let frame=false;const track=document.querySelector('.scroll-track');const lessons=Array.from(document.querySelectorAll('.lesson[data-lecture]:not([data-lecture="0"])'));
 function scrollUpdate(){frame=false;const range=document.documentElement.scrollHeight-innerHeight;track.style.setProperty('--read-progress',range>0?scrollY/range:0);let current=null;for(const l of lessons)if(!l.hidden&&l.getBoundingClientRect().top<200)current=l.id;document.querySelectorAll('.sidebar a[data-lesson]').forEach(a=>a.classList.toggle('current',a.hash==='#'+current))}
 window.addEventListener('scroll',()=>{if(!frame){frame=true;requestAnimationFrame(scrollUpdate)}},{passive:true});window.addEventListener('resize',scrollUpdate);scrollUpdate();
 document.querySelectorAll('details.topic').forEach(el=>el.addEventListener('toggle',()=>{if(el.open&&motionAllowed())el.querySelector('.topic-body').animate([{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:350,easing:'cubic-bezier(.22,1,.36,1)'})}));
 new MutationObserver(()=>{const p=document.querySelector('#study .study-panel');if(p&&motionAllowed())p.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:400,easing:'cubic-bezier(.22,1,.36,1)'});highlight(document.getElementById('study'))}).observe(document.getElementById('study'),{childList:true});
 const escape=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
 function highlight(root){if(!root)return;root.querySelectorAll('pre code').forEach(code=>{if(code.dataset.colored)return;const text=code.textContent;const token=/(\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:class|struct|public|private|protected|virtual|override|final|const|constexpr|explicit|return|int|void|double|auto|if|else|for|while|try|catch|throw|noexcept|default|delete|using|static|friend|mutable|new|bool|nullptr|true|false)\b|\b\d+(?:\.\d+)?\b)/g;let last=0,out='';for(const m of text.matchAll(token)){out+=escape(text.slice(last,m.index));const value=m[0],kind=value.startsWith('//')||value.startsWith('/*')?'comment':value.startsWith('"')||value.startsWith("'")?'string':/^\d/.test(value)?'number':'key';out+='<span class="tok-'+kind+'">'+escape(value)+'</span>';last=m.index+value.length}out+=escape(text.slice(last));code.innerHTML=out;code.dataset.colored='true'})}
 highlight(document.getElementById('reading'));
 // Для лекций из обзорной сетки сохраняется та же навигация по hash.
 document.querySelectorAll('[data-route]').forEach(a=>a.addEventListener('click',()=>{if(location.hash===a.hash)navigateHash()}));
 document.querySelectorAll('header [data-mode]').forEach(b=>b.addEventListener('click',()=>{const r=document.getElementById('study-room').getBoundingClientRect();if(r.top>innerHeight*.6||r.bottom<0)document.getElementById('study-room').scrollIntoView({block:'start'})}));
})();
</script>'''
base=base.replace('</body>',motion+'</body>')
(root/'OOP_CPP20_Motion.html').write_text(base)
print('Created OOP_CPP20_Motion.html:',len(base),'characters;',len(sections),'sections. Markdown and original HTML unchanged.')
